291	  async confirmarColeta(pedidoId: number, motoboyId: number, barcode: string) {
292	    const expected = String(pedidoId).padStart(8, '0');
293	    const scanned  = barcode.replace(/\D/g, '').padStart(8, '0');
294	    if (scanned !== expected) {
295	      throw new BadRequestException('Código de barras não confere com este pedido');
296	    }
