313	    // Troco: sangria automática quando motoboy leva o troco para o cliente
314	    const trocoValor = pedido.payment_method === 'cash' && pedido.troco_para > pedido.total
315	      ? Number(pedido.troco_para) - Number(pedido.total)
316	      : 0;
317	    if (trocoValor > 0) {
318	      const { data: caixa } = await this.supabase.client
319	        .from('caixas')
320	        .select('id, saidas')
321	        .eq('restaurant_id', pedido.restaurant_id)
322	        .eq('status', 'aberto')
323	        .maybeSingle();
324	      if (caixa) {
325	        const saidas = (caixa.saidas ?? []) as any[];
326	        const novaSaida = {
327	          descricao: `Troco pedido #${pedidoId}`,
328	          valor: trocoValor,
329	          meio: 'dinheiro',
330	          criado_em: new Date().toISOString(),
331	        };
332	        await this.supabase.client
333	          .from('caixas')
334	          .update({ saidas: [...saidas, novaSaida] })
335	          .eq('id', caixa.id);
336	      }
337	    }
338	
339	    return { ok: true, pedido_id: pedidoId, status: 'out_for_delivery', troco: trocoValor };
340	  }
