342	  async uploadComprovante(pedidoId: number, motoboyId: number, base64: string) {
343	    const { data: pedido } = await this.supabase.client
344	      .from('orders')
345	      .select('id')
346	      .eq('id', pedidoId)
347	      .eq('motoboy_id', motoboyId)
348	      .maybeSingle();
349	    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');
350	
351	    const matches = base64.match(/^data:(image\/\w+);base64,(.+)$/);
352	    const mimeType = matches ? matches[1] : 'image/jpeg';
353	    const raw = matches ? matches[2] : base64;
354	    const buffer = Buffer.from(raw, 'base64');
355	    const ext = mimeType === 'image/png' ? 'png' : 'jpg';
356	    const path = `pedido-${pedidoId}-${Date.now()}.${ext}`;
357	
358	    const { error: uploadError } = await this.supabase.client.storage
359	      .from('comprovantes-pix')
360	      .upload(path, buffer, { contentType: mimeType, upsert: true });
361	    if (uploadError) throw uploadError;
362	
363	    const { data: { publicUrl } } = this.supabase.client.storage
364	      .from('comprovantes-pix')
365	      .getPublicUrl(path);
366	
367	    await this.supabase.client
368	      .from('orders')
369	      .update({ comprovante_pix_url: publicUrl, updated_at: new Date().toISOString() })
370	      .eq('id', pedidoId);
371	
372	    return { url: publicUrl };
373	  }
