375	  async infoMotoboy(motoboyId: number) {
376	    const { data: mb } = await this.supabase.client
377	      .from('motoboys')
378	      .select('id, name, phone, restaurant_id')
379	      .eq('id', motoboyId)
380	      .maybeSingle();
381	    if (!mb) return null;
382	
383	    const { data: rest } = await this.supabase.client
384	      .from('restaurants')
385	      .select('name, payment_config')
386	      .eq('id', mb.restaurant_id)
387	      .maybeSingle();
388	
389	    return {
390	      ...mb,
391	      restaurante_nome: rest?.name ?? null,
392	      restaurante_cidade: null,
393	      chave_pix: (rest?.payment_config as any)?.chave_pix ?? null,
394	    };
395	  }
396	}
