    taxa_pagbank_percent?: number | null;
    chave_pix?: string | null;
    frete_motoboy?: number;
  },
) {
  const { data: atual } = await this.supabase.client
    .from('restaurants')
    .select('payment_config')
    .eq('id', restaurantId)
