6	
7	const NavRestaurante = ({ active }) => {
8	  const navigate = useNavigate();
9	  const links = [
10	    { label: 'Dashboard', path: '/restaurante' },
11	    { label: 'Produtos', path: '/restaurante/produtos' },
12	    { label: 'Pedidos', path: '/restaurante/pedidos' },
13	    { label: 'Motoboys', path: '/restaurante/motoboys' },
14	    { label: 'Clientes', path: '/restaurante/clientes' },
15	    { label: 'Designer', path: '/restaurante/aparencia' },
16	    { label: 'Config', path: '/restaurante/config' },
17	  ];
18	  return (
19	    <nav className="flex gap-1.5 flex-wrap">
20	      {links.map((l) => (
21	        <button key={l.path} onClick={() => navigate(l.path)}
22	          className={`px-3 py-2 text-sm font-semibold rounded-lg transition-colors ${
23	            active === l.path
24	              ? 'text-white bg-[#FF441F] shadow-sm shadow-[#FF441F]/30'
25	              : 'text-[#27272A] hover:bg-[#F4F4F5]'
26	          }`}>
27	          {l.label}
28	        </button>
29	      ))}
30	    </nav>
31	  );
32	};
33	
34	const RestauranteMotoboys = () => {
35	  const [motoboys, setMotoboys] = useState([]);
36	  const [loading, setLoading] = useState(true);
37	  const [form, setForm] = useState({ name: '', phone: '' });
38	  const [salvando, setSalvando] = useState(false);
39	  const [msg, setMsg] = useState(null);
40	  const [copiado, setCopiado] = useState(null); // { id, tipo } | null
41	  const [renovando, setRenovando] = useState(null); // id | null
42	  const [acesso, setAcesso] = useState(null); // { lan_ips, porta, cloudflare_domain }
43	
44	  const reload = () =>
45	    listarMotoboys()
46	      .then((r) => setMotoboys(r.motoboys ?? []))
47	      .catch((e) => setMsg({ tipo: 'erro', texto: e.message }))
48	      .finally(() => setLoading(false));
49	
50	  useEffect(() => {
51	    reload();
52	    fetch(apiPath('/api/r/acesso'))
53	      .then((r) => r.json())
54	      .then(setAcesso)
55	      .catch(() => {});
56	  }, []);
57	
58	  const handleCriar = async (e) => {
59	    e.preventDefault();
60	    if (!form.name.trim()) return;
61	    setSalvando(true);
62	    try {
63	      await criarMotoboy({ name: form.name.trim(), phone: form.phone.trim() || undefined });
64	      setForm({ name: '', phone: '' });
65	      setMsg({ tipo: 'ok', texto: 'Motoboy criado!' });
66	      setTimeout(() => setMsg(null), 3000);
67	      reload();
68	    } catch (err) {
69	      setMsg({ tipo: 'erro', texto: err.message });
70	    } finally {
71	      setSalvando(false);
72	    }
73	  };
74	
75	  const handleToggle = async (mb) => {
76	    try {
77	      await toggleMotoboy(mb.id, !mb.is_active);
78	      setMotoboys((prev) => prev.map((m) => m.id === mb.id ? { ...m, is_active: !m.is_active } : m));
79	    } catch (err) {
80	      setMsg({ tipo: 'erro', texto: err.message });
81	    }
82	  };
83	
84	  // Funciona em HTTP (LAN) e HTTPS — clipboard API só disponível em contexto seguro
85	  const copiarTexto = (texto) => {
86	    if (navigator.clipboard && window.isSecureContext) {
87	      return navigator.clipboard.writeText(texto);
88	    }
89	    // Fallback para HTTP / dispositivos antigos
90	    const el = document.createElement('textarea');
91	    el.value = texto;
92	    el.style.cssText = 'position:fixed;left:-9999px;top:-9999px';
93	    document.body.appendChild(el);
94	    el.focus();
95	    el.select();
96	    document.execCommand('copy');
97	    document.body.removeChild(el);
98	    return Promise.resolve();
99	  };
100	
101	  const copiar = (texto, id, tipo) => {
102	    copiarTexto(texto).then(() => {
103	      setCopiado({ id, tipo });
104	      setTimeout(() => setCopiado(null), 2500);
105	    });
106	  };
107	
108	  const lanBase = acesso?.lan_ips?.[0]
109	    ? `http://${acesso.lan_ips[0]}:${acesso.porta ?? 4028}`
110	    : null;
111	  const cfBase = acesso?.cloudflare_domain
112	    ? `https://${acesso.cloudflare_domain}`
113	    : null;
114	
115	const copiarLink = async (mb) => {
116	    setRenovando(mb.id);
117	    try {
118	      const atualizado = await renovarTokenMotoboy(mb.id);
119	      setMotoboys((prev) => prev.map((m) => m.id === mb.id ? { ...m, access_token: atualizado.access_token } : m));
120	      const base = cfBase ?? lanBase ?? window.location.origin;
121	      await copiarTexto(`${base}/motoboy?token=${atualizado.access_token}`);
122	      setCopiado({ id: mb.id, tipo: 'link' });
123	      setTimeout(() => setCopiado(null), 2500);
124	    } catch (err) {
125	      setMsg({ tipo: 'erro', texto: 'Erro ao gerar link: ' + err.message });
126	    } finally {
127	      setRenovando(null);
