130	
131	  if (loading) return (
132	    <div className="min-h-screen flex items-center justify-center bg-[#F4F4F5]">
133	      <div className="w-8 h-8 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
134	    </div>
135	  );
136	
137	  return (
138	    <div className="min-h-screen bg-[#F4F4F5]">
139	      <header className="bg-white border-b border-[#E4E4E7] px-4 sm:px-6 py-4">
