142	            <h1 className="text-xl font-black text-[#18181B]">Motoboys</h1>
143	            <p className="text-sm text-[#71717A]">Cadastro e links de acesso</p>
144	          </div>
145	          <NavRestaurante active="/restaurante/motoboys" />
146	        </div>
147	      </header>
148	
149	      <main className="max-w-2xl mx-auto px-4 py-6 space-y-5">
150	        {/* Aviso de acesso */}
151	        {acesso && !cfBase && (
152	          <div className="rounded-xl border px-4 py-2.5 text-xs bg-amber-50 border-amber-200 text-amber-800">
153	            ⚠️ Link funciona apenas na mesma rede WiFi. Para acesso externo configure Cloudflare em <strong>Admin → Configurações</strong>.
154	          </div>
155	        )}
156	        {/* Form novo motoboy */}
157	        <div className="bg-white rounded-2xl border border-[#E4E4E7] p-5">
158	          <h2 className="font-bold text-[#18181B] text-sm mb-4 flex items-center gap-2">
