162	            <input
163	              value={form.name}
164	              onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
165	              placeholder="Nome"
166	              required
167	              className="flex-1 border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]"
168	            />
