182	        {msg && (
183	          <div className={`text-sm rounded-xl px-4 py-3 ${
184	            msg.tipo === 'ok' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-600 border border-red-200'
185	          }`}>
186	            {msg.texto}
187	          </div>
188	        )}
189	
190	        {/* Lista */}
